export class QuotePage {
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly injector = inject(Injector);
  protected readonly store = inject(QuoteState);
  protected readonly page = signal<QuoteRoute | null>(null);
  protected readonly invalid = signal(false);
  private routeKey = '';
  private priorPhase: string | undefined;

  constructor() {
    this.route.paramMap.pipe(takeUntilDestroyed()).subscribe((params) => {
      const rawCountry = params.get('country');
      const rawStep = params.get('step');
      const country =
        rawCountry === 'CO' || rawCountry === 'CL' ? rawCountry.toLowerCase() : rawCountry;
      if (!isCountry(country)) {
        this.store.leave();
        this.page.set(null);
        this.invalid.set(true);
        return;
      }
      if (rawCountry !== country || (rawStep !== 'details' && rawStep !== 'plans')) {
        if (this.page()?.country !== country) this.store.leave();
        this.page.set(null);
        const nextStep = rawStep === 'plans' ? 'plans' : 'details';
        void this.router.navigate(['/', country, 'quote', nextStep], { replaceUrl: true });
        return;
      }
      this.invalid.set(false);
      this.page.set({ country, step: rawStep });
      this.store.load(country);
    });

    effect(() => {
      const page = this.page();
      const state = this.store.state();
      if (!page || state.phase === 'idle' || state.country !== page.country) return;
      const key = `${page.country}/${page.step}`;
      const previous = key === this.routeKey ? this.priorPhase : undefined;
      this.routeKey = key;
      this.priorPhase = state.phase;
      if (
        state.phase === 'ready' &&
        page.step === 'plans' &&
        !this.store.canContinue(page.country)
      ) {
        void this.router.navigate(['/', page.country, 'quote', 'details'], { replaceUrl: true });
        return;
      }
      if (state.phase === 'unavailable') this.focus('configuration-error');
      else if (previous === undefined || (previous === 'loading' && state.phase === 'ready')) {
        this.focus('screen-heading');
      }
    });
  }

  protected advance(country: Country) {
    if (this.store.canContinue(country))
      void this.router.navigate(['/', country, 'quote', 'plans']);
  }

  private focus(target: string) {
    afterNextRender(() => document.getElementById(target)?.focus(), { injector: this.injector });
  }
}

import type { Core } from "@strapi/strapi";
import { FORM_UID } from "./api/quote-content/form-projection";
import { READ_FORM_ACTION } from "./api/quote-content/routes/quote-content";
import { seedForm } from "./seed-forms";

async function restrictPublicRole(strapi: Core.Strapi) {
  await strapi.db.transaction(async () => {
    const roles = strapi.db.query("plugin::users-permissions.role");
    const publicRole = await roles.findOne({ where: { type: "public" } });
    if (!publicRole)
      throw new Error(
        "The Public role is unavailable during quote initialization.",
      );

    const permissions = strapi.db.query("plugin::users-permissions.permission");
    const grants = await permissions.findMany({
      select: ["id", "action"],
      where: { role: publicRole.id },
    });
    const reader = grants.find(({ action }) => action === READ_FORM_ACTION);
    const obsolete = grants
      .filter(({ id }) => id !== reader?.id)
      .map(({ id }) => id);
    if (obsolete.length) {
      await permissions.deleteMany({ where: { id: { $in: obsolete } } });
    }
    if (!reader) {
      await permissions.create({
        data: { action: READ_FORM_ACTION, role: publicRole.id },
      });
    }
  });
}

export default {
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    await restrictPublicRole(strapi);

    const seedState = strapi.store({ type: "core", name: "quote-content" });
    if (await seedState.get({ key: "us01-seeded" })) return;

    for (const country of ["co", "cl"] as const) {
      const documents = strapi.documents(FORM_UID);
      const draft = await documents.findFirst({
        status: "draft",
        filters: { country },
      });
      if (!draft)
        await documents.create({
          data: seedForm(country),
          status: "published",
        });
    }
    await seedState.set({ key: "us01-seeded", value: true });
  },
};
