import type { Core } from "@strapi/strapi";
import { FORM_UID } from "./api/quote-content/form-projection";
import { READ_FORM_ACTION } from "./api/quote-content/routes/quote-content";
import { seedForm } from "./seed-forms";

async function restrictPublicRole(strapi: Core.Strapi) {
  await strapi.db.transaction(async () => {
    const roles = strapi.db.query("plugin::users-permissions.role");
    const publicRole = await roles.findOne({ where: { type: "public" } });
    if (!publicRole)
      throw new Error(
        "The Public role is unavailable during quote initialization.",
      );

    const permissions = strapi.db.query("plugin::users-permissions.permission");
    const grants = await permissions.findMany({
      select: ["id", "action"],
      where: { role: publicRole.id },
    });
    const reader = grants.find(({ action }) => action === READ_FORM_ACTION);
    const obsolete = grants
      .filter(({ id }) => id !== reader?.id)
      .map(({ id }) => id);
    if (obsolete.length) {
      await permissions.deleteMany({ where: { id: { $in: obsolete } } });
    }
    if (!reader) {
      await permissions.create({
        data: { action: READ_FORM_ACTION, role: publicRole.id },
      });
    }
  });
}

export default {
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    await restrictPublicRole(strapi);

    const seedState = strapi.store({ type: "core", name: "quote-content" });
    if (await seedState.get({ key: "us01-seeded" })) return;

    for (const country of ["co", "cl"] as const) {
      const documents = strapi.documents(FORM_UID);
      const draft = await documents.findFirst({
        status: "draft",
        filters: { country },
      });
      if (!draft)
        await documents.create({
          data: seedForm(country),
          status: "published",
        });
    }
    await seedState.set({ key: "us01-seeded", value: true });
  },
};
import { isCountry } from "@quote/contract";
import { FORM_UID, projectForm } from "../form-projection";

type ReadContext = {
  params: Record<string, unknown>;
  querystring: string;
  set(name: string, value: string): void;
  status: number;
  body: unknown;
};

export default {
  async readForm(ctx: ReadContext) {
    ctx.set("Cache-Control", "no-store");
    const fail = (status: number, code: string) => {
      ctx.body = { error: { code } };
      ctx.status = status;
    };

    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(FORM_UID).findMany({
        status: "published",
        filters: { country },
        populate: { fields: { populate: ["options", "rules"] } },
        limit: 2,
      });
    } catch {
      strapi.log.error("Quote form document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    if (!documents.length) return fail(404, "FORM_NOT_PUBLISHED");
    const form =
      documents.length === 1 ? projectForm(documents[0], country) : null;
    if (!form) {
      strapi.log.warn("A published quote form configuration was rejected.");
      return fail(503, "FORM_UNAVAILABLE");
    }
    ctx.body = form;
    ctx.status = 200;
  },
};
export const READ_FORM_ACTION = "api::quote-content.quote-content.readForm";

export default {
  routes: [
    {
      method: "GET",
      path: "/quote-content/v1/:country/form",
      handler: READ_FORM_ACTION,
      config: { auth: { scope: [READ_FORM_ACTION] } },
    },
  ],
};
